`timescale 1ns / 1ps
// -----------------------------------------------------------------------------
// Inverse-sinc droop compensator + decimate-by-DEC.
// Input arrives at CIC output rate (in_valid pulses); one output is computed
// every DEC-th input using a single time-shared multiplier (NTAPS clocks).
// Coefficients come from fir_coef_rom.v (generated by task2_fir_comp.m).
// -----------------------------------------------------------------------------
module fir_comp #(
    parameter NTAPS = 63,
    parameter AW    = 4,          // ceil(log2(NTAPS))
    parameter DW    = 20,         // input width
    parameter CW    = 18,         // coefficient width (Q1.17)
    parameter FRAC  = 17,         // coefficient fractional bits
    parameter DEC   = 4,
    parameter OW    = 20          // output width (max 20)
)(
    input  wire                  clk,
    input  wire                  reset,
    input  wire                  in_valid,
    input  wire signed [DW-1:0]  din,
    output reg  signed [OW-1:0]  dout,
    output reg                   out_valid
);

    localparam ACCW = DW + CW + AW + 1;
    localparam DCW  = (DEC > 1) ? $clog2(DEC) : 1;

    localparam [1:0] IDLE = 2'd0, RUN = 2'd1, DONE = 2'd2;

    reg signed [DW-1:0]   sbuf [0:NTAPS-1];   // circular sample buffer
    reg [AW-1:0]          wp;                 // write pointer
    reg [AW-1:0]          rp;                 // read pointer (newest -> oldest)
    reg [AW-1:0]          k;                  // tap index
    reg [DCW-1:0]         dcnt;
    reg [1:0]             st;
    reg signed [ACCW-1:0] acc;

    integer n;
    initial for (n = 0; n < NTAPS; n = n + 1) sbuf[n] = {DW{1'b0}};

    wire signed [CW-1:0]     coef;
    fir_coef_rom #(.AW(AW), .CW(CW)) u_rom (.addr(k), .coef(coef));

    wire signed [DW-1:0]     samp = sbuf[rp];
    wire signed [DW+CW-1:0]  prod = samp * coef;

    localparam signed [ACCW-1:0] RNDC = {{(ACCW-1){1'b0}}, 1'b1} << (FRAC-1);
    localparam signed [ACCW-1:0] MAXV = (1 <<< (OW-1)) - 1;
    localparam signed [ACCW-1:0] MINV = -(1 <<< (OW-1));

    wire signed [ACCW-1:0] scaled = (acc + RNDC) >>> FRAC;

    always @(posedge clk) begin
        if (reset) begin
            wp <= 0; rp <= 0; k <= 0; dcnt <= 0;
            st <= IDLE; acc <= 0; dout <= 0; out_valid <= 1'b0;
        end else begin
            out_valid <= 1'b0;

            case (st)
                RUN: begin
                    acc <= acc + prod;
                    if (k == NTAPS-1) st <= DONE;
                    else begin
                        k  <= k + 1'b1;
                        rp <= (rp == 0) ? NTAPS-1 : rp - 1'b1;
                    end
                end
                DONE: begin
                    if      (scaled > MAXV) dout <= MAXV[OW-1:0];
                    else if (scaled < MINV) dout <= MINV[OW-1:0];
                    else                    dout <= scaled[OW-1:0];
                    out_valid <= 1'b1;
                    st        <= IDLE;
                end
                default: ;
            endcase

            // new input sample (arrives while idle, RUN takes only NTAPS clks)
            if (in_valid) begin
                sbuf[wp] <= din;
                wp       <= (wp == NTAPS-1) ? {AW{1'b0}} : wp + 1'b1;
                if (dcnt == DEC-1) begin
                    dcnt <= 0;
                    st   <= RUN;
                    k    <= 0;
                    rp   <= wp;          // newest sample (written this clock)
                    acc  <= 0;
                end else
                    dcnt <= dcnt + 1'b1;
            end
        end
    end

endmodule